  if quote:
   cur+=c
   if c==quote:quote=None
  elif c in "'\"": quote=c;cur+=c
  elif c in '[{(':depth+=1;cur+=c
  elif c in ']})':depth-=1;cur+=c
  elif c==',' and depth==0:out.append(cur.strip());cur=''
  else:cur+=c
 if cur.strip():out.append(cur.strip())
 return out

def key_value(s):
 # A YAML mapping delimiter is followed by whitespace or ends the key. This
 # matters for Task's `namespace:task` task names, whose final colon is the
 # actual delimiter.
 m=re.match(r'^(.*?):(?:\s+(.*)|\s*)$',s)
 if not m:return None,None
 return m.group(1).strip(),(m.group(2) or '').strip()

def block_value(chunks, indicator):
