 else:
  pieces=[]
  for index,chunk in enumerate(chunks):
   if index:
    if not chunk:pieces.append('\n')
    elif not chunks[index-1]:pass
    else:pieces.append(' ')
   pieces.append(chunk)
  value=''.join(pieces)
